    const form = document.getElementById('contact-form');
    const nameInput = document.getElementById('full-name');
    const emailInput = document.getElementById('email');

    form.addEventListener('submit', (event) => {
        event.preventDefault();

        // Reset errors and status
        resetErrors();
        const status = document.getElementById('form-status');
        status.textContent = '';
        status.className = 'status-message';
        status.style.display = 'none';

        let firstInvalid = null;

        // Validate Name
        if (!nameInput.value.trim()) {
            setError(nameInput, 'Full Name is required');
            firstInvalid = firstInvalid || nameInput;
        }

        // Validate Email
        if (!emailInput.value.trim()) {
            setError(emailInput, 'Email Address is required');
            firstInvalid = firstInvalid || emailInput;
        } else if (!isValidEmail(emailInput.value.trim())) {
            setError(emailInput, 'Please enter a valid email address');
            firstInvalid = firstInvalid || emailInput;
        }

        if (firstInvalid) {
            firstInvalid.focus();
        } else {
            // Success
            showSuccess('Form submitted successfully! We will contact you soon.');
            form.reset();
            resetErrors();
        }
    });

    function showSuccess(message) {
        const status = document.getElementById('form-status');
        status.textContent = message;
        status.className = 'status-message success';
    }

    function isValidEmail(email) {
        return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
    }

    function setError(input, message) {
        input.classList.add('invalid');
        input.setAttribute('aria-invalid', 'true');

        // Find the error message container in the same form-field
        const errorContainer = input.parentElement.querySelector('.error-message');
        if (errorContainer) {
            errorContainer.textContent = message;
            // Associate with input if not already
            const errorId = input.id + '-error-msg';
            errorContainer.id = errorId;

            // Handle aria-describedby carefully to not overwrite existing (like phone helper)
            const existingDescribedBy = input.getAttribute('aria-describedby') || '';
            if (!existingDescribedBy.includes(errorId)) {
                input.setAttribute('aria-describedby', `${existingDescribedBy} ${errorId}`.trim());
            }
        }
    }

    function resetErrors() {
        const inputs = form.querySelectorAll('input');
        inputs.forEach(input => {
            input.classList.remove('invalid');
            input.removeAttribute('aria-invalid');

            // Remove error message from aria-describedby
            const errorId = input.id + '-error-msg';
            const existingDescribedBy = input.getAttribute('aria-describedby') || '';
            const newDescribedBy = existingDescribedBy.replace(errorId, '').trim();
            if (newDescribedBy) {
                input.setAttribute('aria-describedby', newDescribedBy);
            } else {
                input.removeAttribute('aria-describedby');
                // Re-add phone helper if it was there
                if (input.id === 'phone') {
                    input.setAttribute('aria-describedby', 'phone-helper');
                }
            }
        });

        const errorMessages = form.querySelectorAll('.error-message');
        errorMessages.forEach(msg => {
            msg.textContent = '';
        });
    }
});
